using System;
using System.IO;
using System.Collections.Generic;
using System.Security.Cryptography;
namespace VintageCollector.EditorTools {
 // Pure fail-closed policy; no creation/deletion or Unity dependency.
 public static class Phase5BuildPolicy {
  public const string Root="F:/[WORKSPACE]/[HERMES]/[CHATGPT]/PokemonThrowbackTCG";
  public static void Safe(string path){string parent=Path.GetDirectoryName(path);if(!string.IsNullOrEmpty(parent)&&parent!=path)Safe(parent);try{if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new ArgumentException("Reparse path refused: "+path);}catch(FileNotFoundException){}catch(DirectoryNotFoundException){}}
  static string Full(string path){if(string.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path))throw new ArgumentException("Absolute project path required");string p=Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);Safe(p);return p;}
  public static string RequireOwnedStage(string current,string root){root=Full(root);string stage=Full(Path.Combine(root,".artifacts","phase5-build-project"));if(!string.Equals(Full(current),stage,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Exact Phase5 stage required; Root/cousins refused");RequireRegularTree(stage);string marker=Path.Combine(stage,".phase5-stage-owner.txt");Safe(marker);if(!File.Exists(marker)||File.ReadAllText(marker)!="phase5-exact-source-v1\n"+root.Replace('\\','/')+"\n")throw new InvalidOperationException("Foreign/unowned stage");return stage;}
  // Attributes only: inspect links before traversal, with no cache hashes or preservation prunes.
  public static void RequireRegularTree(string directory){Safe(directory);FileAttributes root;try{root=File.GetAttributes(directory);}catch(FileNotFoundException){return;}catch(DirectoryNotFoundException){return;}if((root&FileAttributes.Directory)==0)throw new InvalidOperationException("Non-regular write tree: "+directory);var pending=new Stack<string>();pending.Push(directory);while(pending.Count!=0)foreach(string child in Directory.GetFileSystemEntries(pending.Pop())){FileAttributes attrs=File.GetAttributes(child);if((attrs&FileAttributes.ReparsePoint)!=0)throw new ArgumentException("Reparse path refused: "+child);if((attrs&FileAttributes.Device)!=0)throw new InvalidOperationException("Non-regular write input: "+child);if((attrs&FileAttributes.Directory)!=0)pending.Push(child);else if(!File.Exists(child))throw new InvalidOperationException("Non-regular write input: "+child);}}
  public static string Resolve(string root){string output=Path.Combine(Full(root),"Builds","Phase5Windows");Safe(output);if(File.Exists(output))throw new InvalidOperationException("Output is a file");if(Directory.Exists(output))foreach(string child in Directory.GetFileSystemEntries(output)){Safe(child);if(string.Equals(Path.GetFileName(child),"Saves",StringComparison.OrdinalIgnoreCase)&&(!Directory.Exists(child)||Directory.GetFileSystemEntries(child).Length!=0))throw new InvalidOperationException("Populated candidate Saves blocks build");}if(Directory.Exists(output)){RequireRegularTree(output);bool members=false;foreach(string child in Directory.GetFileSystemEntries(output))if(!string.Equals(Path.GetFileName(child),"Saves",StringComparison.OrdinalIgnoreCase))members=true;if(members){string marker=Path.Combine(output,".phase5-candidate-owner.txt");Safe(marker);if(!File.Exists(marker)||File.ReadAllText(marker)!="phase5-candidate-v1\n"+Full(root).Replace('\\','/')+"\n")throw new InvalidOperationException("Foreign candidate output");}}return output;}
  public static string Hash(string path){Safe(path);using(var h=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  public static IDictionary<string,string> CompilerManifest(string directory){string root=Full(directory);var pins=new SortedDictionary<string,string>(StringComparer.Ordinal);if(Directory.Exists(root))Walk(root,root,pins);return pins;}
  static void Walk(string root,string directory,IDictionary<string,string> pins){foreach(string path in Directory.GetFileSystemEntries(directory)){Safe(path);if(Directory.Exists(path))Walk(root,path,pins);else pins.Add(path.Substring(root.Length+1).Replace('\\','/'),Hash(path));}}
  public static IDictionary<string,string> AllInputs(string project){var all=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(string tree in new[]{"Assets","Packages","ProjectSettings"})foreach(var item in CompilerManifest(Path.Combine(project,tree)))all.Add(tree+"/"+item.Key,item.Value);return all;}
  public static void RequirePins(string project,string pinFile){Safe(pinFile);var expected=new Dictionary<string,string>(StringComparer.Ordinal);foreach(string line in File.ReadAllLines(pinFile)){string[] bits=line.Split('\t');if(bits.Length!=2||bits[0].Length!=64||bits[1].Contains("\\")||bits[1].Contains("..")||!(bits[1].StartsWith("Assets/",StringComparison.Ordinal)||bits[1].StartsWith("Packages/",StringComparison.Ordinal)||bits[1].StartsWith("ProjectSettings/",StringComparison.Ordinal)))throw new InvalidOperationException("Malformed frozen compiler pin");expected.Add(bits[1],bits[0]);}var actual=AllInputs(project);var allowed=new HashSet<string>(StringComparer.Ordinal);string allowFile=Path.Combine(project,".phase5-native-meta-allowlist.txt");Safe(allowFile);if(File.Exists(allowFile))foreach(string n in File.ReadAllLines(allowFile)){if(!n.StartsWith("Assets/",StringComparison.Ordinal)||!n.EndsWith(".meta",StringComparison.Ordinal)||n.Contains("..")||n.Contains("\\"))throw new InvalidOperationException("Invalid native meta allowance");allowed.Add(n);}foreach(var item in actual)if(!expected.ContainsKey(item.Key)){string native=Path.Combine(project,item.Key);if(!allowed.Contains(item.Key)||!System.Text.RegularExpressions.Regex.IsMatch(File.ReadAllText(native),"(?m)^guid: [0-9a-f]{32}$")||new FileInfo(native).Length>4096)throw new InvalidOperationException("Unexpected compiler member "+item.Key);}foreach(var pin in expected){string d;if(!actual.TryGetValue(pin.Key,out d)||d!=pin.Value)throw new InvalidOperationException("Source-byte pin mismatch "+pin.Key);}}
  public static string Admit(string current,string action){string stage=RequireOwnedStage(current,Root);Resolve(Root);string auth=Path.Combine(stage,".phase5-authorization.txt");Safe(auth);if(!File.Exists(auth)||File.ReadAllText(auth)!="phase5-parent-authorized-v1\n"+action+"\n")throw new InvalidOperationException("Explicit parent-authorized action required");RequirePins(Root,Path.Combine(stage,".phase5-root-pins.tsv"));RequirePins(stage,Path.Combine(stage,".phase5-stage-pins.tsv"));return stage;}
 }
}
